154	sealed class NotificationWorker : BackgroundService
155	{
156	    readonly Channel<Notification> _ch; readonly Metrics _m; readonly JsonlLog _log; readonly HttpClient _http = new();
157	    readonly string _sink = Environment.GetEnvironmentVariable("OC_SINK_URL") ?? "http://127.0.0.1:5081/notify";
158	    static readonly int[] Backoff = { 200, 400, 800 };
159	    const int MaxDeferrals = 5;
160	    public NotificationWorker(Channel<Notification> ch, Metrics m, JsonlLog log) { _ch = ch; _m = m; _log = log; }
161	    static readonly HttpClient SharedHttp = new();
162	    /// 同步送一次（含重試）；計數規則與 worker 相同。
163	    public static async Task SendOnce(Notification n, Metrics m, JsonlLog log, string sink)
164	    {
165	        bool sent = false;
166	        for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
167	        {
168	            try
169	            {
170	                var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
171	                var resp = await SharedHttp.PostAsync(sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"));
172	                sent = resp.IsSuccessStatusCode;
173	            }
174	            catch (Exception e) { log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name }); }
175	            if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt]);
176	        }
177	        if (sent) { m.Inc("notify_sent_total"); log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, sync = true }); }
178	        else { m.Inc("notify_failed_total"); m.Inc("notify_dead_letter_total"); log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 }); }
179	    }
180	    protected override async Task ExecuteAsync(CancellationToken ct)
181	    {
182	        await foreach (var n in _ch.Reader.ReadAllAsync(ct))
183	        {
184	            bool sent = false;
185	            for (int attempt = 0; attempt <= Backoff.Length && !sent; attempt++)
186	            {
187	                try
188	                {
189	                    var body = JsonSerializer.Serialize(new { notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, kind = n.Kind, refund_requested = n.RefundRequested, attempt });
190	                    var resp = await _http.PostAsync(_sink, new StringContent(body, System.Text.Encoding.UTF8, "application/json"), ct);
191	                    sent = resp.IsSuccessStatusCode;
192	                    if (!sent) _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, status = (int)resp.StatusCode });
193	                }
194	                catch (Exception e) when (!ct.IsCancellationRequested)
195	                {
196	                    _log.Write(new { level = "WARN", @event = "notify_attempt_failed", notification_id = n.NotificationId, attempt, error = e.GetType().Name });
197	                }
198	                if (!sent && attempt < Backoff.Length) await Task.Delay(Backoff[attempt], ct);
199	            }
200	            if (sent)
201	            {
202	                _m.Inc("notify_sent_total");
203	                _log.Write(new { level = "INFO", @event = "notify_sent", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId });
204	            }
205	            else
206	            {
207	                _m.Inc("notify_failed_total"); _m.Inc("notify_dead_letter_total");
208	                _log.Write(new { level = "ERROR", @event = "notify_dead_letter", notification_id = n.NotificationId, order_id = n.OrderId, request_id = n.RequestId, run_id = n.RunId, attempts = Backoff.Length + 1 });
209	            }
210	        }
211	    }
212	}
